"use strict";

const FEELINGS = new Set(["calm", "worried", "focused", "tired"]);
const hasOwn = (object, key) => Object.prototype.hasOwnProperty.call(object, key);

function createFeelingState() {
  return { feeling: "calm", stateSwitch: false, reducerSwitch: false };
}

function validateState(state) {
  if (state === null || typeof state !== "object" || Array.isArray(state) ||
      !hasOwn(state, "feeling") || !hasOwn(state, "stateSwitch") ||
      !hasOwn(state, "reducerSwitch") || !FEELINGS.has(state.feeling) ||
      typeof state.stateSwitch !== "boolean" ||
      typeof state.reducerSwitch !== "boolean") {
    throw new TypeError("invalid state");
  }
}

function reduceFeelingState(state, action, log) {
  validateState(state);
  if (typeof log !== "function" || action === null || typeof action !== "object" ||
      Array.isArray(action) || !hasOwn(action, "type")) {
    throw new TypeError("invalid arguments");
  }
  if (action.type === "select") {
    if (!hasOwn(action, "feeling") || !FEELINGS.has(action.feeling)) {
      throw new TypeError("unsupported feeling");
    }
    log(action.feeling);
    return { ...state, feeling: action.feeling };
  }
  if (action.type === "toggle-state") {
    if (hasOwn(action, "feeling")) throw new TypeError("invalid toggle action");
    return { ...state, stateSwitch: !state.stateSwitch };
  }
  if (action.type === "toggle-reducer") {
    if (hasOwn(action, "feeling")) throw new TypeError("invalid toggle action");
    return { ...state, stateSwitch: !state.stateSwitch };
  }
  throw new TypeError("unsupported action");
}

module.exports = { createFeelingState, reduceFeelingState };

