"use strict";

const assert = require("node:assert/strict");
const api = require("./solution");
assert.deepStrictEqual(Object.keys(api).sort(), ["createFeelingState", "reduceFeelingState"]);
const { createFeelingState, reduceFeelingState } = api;

const initial = createFeelingState();
assert.deepStrictEqual(initial, { feeling: "calm", stateSwitch: false, reducerSwitch: false });
assert.notStrictEqual(initial, createFeelingState());

const logged = [];
const selected = reduceFeelingState(initial, { type: "select", feeling: "worried", ignored: 1 }, (value) => logged.push(value));
assert.deepStrictEqual(selected, { feeling: "worried", stateSwitch: false, reducerSwitch: false });
assert.deepStrictEqual(initial, { feeling: "calm", stateSwitch: false, reducerSwitch: false });
assert.notStrictEqual(selected, initial);
assert.deepStrictEqual(logged, ["worried"]);

const same = reduceFeelingState(initial, { type: "select", feeling: "calm" }, (value) => logged.push(value));
assert.deepStrictEqual(same, initial);
assert.notStrictEqual(same, initial);
assert.deepStrictEqual(logged, ["worried", "calm"]);

for (const feeling of ["focused", "tired"]) {
  const values = [];
  const result = reduceFeelingState(initial, { type: "select", feeling }, (value) => values.push(value));
  assert.strictEqual(result.feeling, feeling);
  assert.deepStrictEqual(values, [feeling]);
}

let logCalls = 0;
const stateToggled = reduceFeelingState(selected, { type: "toggle-state", extra: true }, () => { logCalls += 1; });
assert.deepStrictEqual(stateToggled, { feeling: "worried", stateSwitch: true, reducerSwitch: false });
const reducerToggled = reduceFeelingState(stateToggled, { type: "toggle-reducer" }, () => { logCalls += 1; });
assert.deepStrictEqual(reducerToggled, { feeling: "worried", stateSwitch: true, reducerSwitch: true });
assert.strictEqual(logCalls, 0);
assert.notStrictEqual(stateToggled, selected);
assert.notStrictEqual(reducerToggled, stateToggled);

const invalidStates = [
  null,
  {},
  { feeling: "calm", stateSwitch: false },
  { feeling: "calm", reducerSwitch: false },
  { stateSwitch: false, reducerSwitch: false },
  { feeling: "angry", stateSwitch: false, reducerSwitch: false },
  { feeling: "calm", stateSwitch: 0, reducerSwitch: false },
  { feeling: "calm", stateSwitch: false, reducerSwitch: "false" }
];
for (const state of invalidStates) {
  assert.throws(() => reduceFeelingState(state, { type: "toggle-state" }, () => {}), TypeError);
}

const invalidActions = [
  null,
  [],
  {},
  { type: "select" },
  { type: "select", feeling: "happy" },
  { type: "select", feeling: 1 },
  { type: "toggle-state", feeling: "calm" },
  { type: "other" }
];
for (const action of invalidActions) {
  assert.throws(() => reduceFeelingState(initial, action, () => {}), TypeError);
}
for (const invalidLog of [null, {}, "log", 1]) {
  assert.throws(() => reduceFeelingState(initial, { type: "toggle-state" }, invalidLog), TypeError);
}

